/**
 * upsert-e2e-auth-user.mjs — makes the E2E identity exist in the local GoTrue.
 *
 * WHY THIS SCRIPT EXISTS
 * The E2E specs sign in through the real login form, so the identity has to exist
 * in Supabase Auth — the fixture only creates the `USUARIO` row in Postgres. Two
 * identities with the same `nombreUsuario` must line up or every spec fails at
 * login. Historically that identity lived in the hosted project and its password
 * was a GitHub secret; against the ephemeral local stack it is created here, per
 * run, with a password generated by the caller and never printed.
 *
 * WHAT IT DOES (find-or-create, then prove it):
 *   1. Looks the user up by its synthetic email.
 *   2. Updates its password when it already exists, creates it (email confirmed)
 *      when it does not.
 *   3. VERIFIES the password grant against the public token endpoint — the same
 *      call the app's login makes — so a misconfigured Auth fails here instead of
 *      surfacing as a login timeout inside Playwright.
 *
 * ENV (all required):
 *   SUPABASE_URL        local stack API URL (http://127.0.0.1:54321)
 *   SERVICE_ROLE_KEY    local stack service role key (admin API)
 *   ANON_KEY            local stack anon key (password grant)
 *   E2E_USER            nombreUsuario of the identity (e.g. e2e-automation)
 *   E2E_AUTH_PASSWORD   password to set (passed via env so it never reaches argv)
 *
 * The synthetic email format mirrors `buildSyntheticEmail` in
 * app/src/modules/auth/domain/synthetic-email.ts (ADR-014: the email is never a
 * credential, only an internal key). Drift between the two breaks the suite
 * loudly, and the grant verification below catches it before Playwright starts.
 */

const SYNTHETIC_EMAIL_SUFFIX = "@users.systemfact.internal";

const {
  SUPABASE_URL,
  SERVICE_ROLE_KEY,
  ANON_KEY,
  E2E_USER,
  E2E_AUTH_PASSWORD,
} = process.env;

for (const [key, value] of Object.entries({
  SUPABASE_URL,
  SERVICE_ROLE_KEY,
  ANON_KEY,
  E2E_USER,
  E2E_AUTH_PASSWORD,
})) {
  if (!value) {
    console.error(`FAIL: upsert-e2e-auth-user: ${key} is not set.`);
    process.exit(1);
  }
}

const baseUrl = SUPABASE_URL.replace(/\/+$/, "");
const email = `${E2E_USER}${SYNTHETIC_EMAIL_SUFFIX}`;
const adminHeaders = {
  apikey: SERVICE_ROLE_KEY,
  Authorization: `Bearer ${SERVICE_ROLE_KEY}`,
  "Content-Type": "application/json",
};

async function request(path, init = {}) {
  const response = await fetch(`${baseUrl}${path}`, init);
  const text = await response.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { ok: response.ok, status: response.status, body };
}

function describe(result) {
  return `HTTP ${result.status} ${typeof result.body === "string" ? result.body : JSON.stringify(result.body)}`;
}

/** Paginates the admin user list; returns the matching user or undefined. */
async function findUser() {
  const perPage = 200;
  for (let page = 1; page <= 50; page += 1) {
    const result = await request(`/auth/v1/admin/users?page=${page}&per_page=${perPage}`, {
      headers: adminHeaders,
    });
    if (!result.ok) {
      throw new Error(`listing auth users failed: ${describe(result)}`);
    }
    const users = result.body?.users ?? [];
    const match = users.find((user) => user.email === email);
    if (match) return match;
    const total = Number(result.body?.aud ?? 0) || 0;
    if (users.length < perPage || page * perPage >= total) return undefined;
  }
  return undefined;
}

const existing = await findUser();

if (existing) {
  const updated = await request(`/auth/v1/admin/users/${existing.id}`, {
    method: "PUT",
    headers: adminHeaders,
    body: JSON.stringify({ password: E2E_AUTH_PASSWORD, email_confirm: true }),
  });
  if (!updated.ok) {
    throw new Error(`updating the auth user ${existing.id} failed: ${describe(updated)}`);
  }
  console.log(`==> auth user exists (${existing.id}); password updated`);
} else {
  const created = await request("/auth/v1/admin/users", {
    method: "POST",
    headers: adminHeaders,
    body: JSON.stringify({
      email,
      password: E2E_AUTH_PASSWORD,
      email_confirm: true,
    }),
  });
  if (!created.ok) {
    throw new Error(`creating the auth user failed: ${describe(created)}`);
  }
  console.log(`==> auth user created (${created.body?.id})`);
}

// Prove the credential the app will use. This is the same grant as the login form.
const grant = await request("/auth/v1/token?grant_type=password", {
  method: "POST",
  headers: { apikey: ANON_KEY, "Content-Type": "application/json" },
  body: JSON.stringify({ email, password: E2E_AUTH_PASSWORD }),
});
if (!grant.ok || !grant.body?.access_token) {
  throw new Error(`the password grant for ${email} failed: ${describe(grant)}`);
}
console.log("==> password grant verified (session issued)");
